import { Hono } from './hono'
import { setCookie } from './helper/cookie'

const dump = (res: Response) => res.headers.getSetCookie()

describe('scratch', () => {
  it('A: c.res.headers set-cookie before next', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      c.res.headers.append('set-cookie', 'mw=1; Path=/')
      await next()
    })
    app.get('/', () => new Response('ok', { headers: { 'set-cookie': 'handler=1; Path=/' } }))
    const res = await app.request('/')
    console.log('A', dump(res))
  })
  it('B: setCookie before next', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      setCookie(c, 'mw', '1', { path: '/' })
      await next()
    })
    app.get('/', () => new Response('ok', { headers: { 'set-cookie': 'handler=1; Path=/' } }))
    const res = await app.request('/')
    console.log('B', dump(res))
  })
  it('C: setCookie after next', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      await next()
      setCookie(c, 'mw', '1', { path: '/' })
    })
    app.get('/', () => new Response('ok', { headers: { 'set-cookie': 'handler=1; Path=/' } }))
    const res = await app.request('/')
    console.log('C', dump(res))
  })
  it('D: middleware sets on c.res then handler returns c.text with cookie header', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      c.res.headers.append('set-cookie', 'mw=1; Path=/')
      await next()
    })
    app.get('/', (c) => c.text('ok', 200, { 'set-cookie': 'handler=1; Path=/' }))
    const res = await app.request('/')
    console.log('D', dump(res))
  })
})
EOF
